// ── STEP 1: Reproduce with a minimal failing case ─────────────
// Bug reported: "cart totals are sometimes wrong"
// WRONG: open the 800-line CartPage component and start reading
// RIGHT: extract and test the calculation function in isolation

function calcCartTotal(items) {
  return items.reduce((sum, item) => sum + item.price * item.qty, 0);
}

// Minimal reproduction — try a variety of inputs:
console.log(calcCartTotal([{ price: 9.99, qty: 2 }]));    // → 19.98 ✓
console.log(calcCartTotal([{ price: 9.99, qty: '2' }]));   // → '019.9819.98' ✗ BUG
console.log(calcCartTotal([{ price: 9.99, qty: 0 }]));    // → 0 ✓
console.log(calcCartTotal([]));                            // → 0 ✓

// Hypothesis confirmed: qty arrives as a string from the API.
// String * Number = NaN when there's no implicit coercion context,
// but the `+` in reduce concatenates. The fix:
function calcCartTotalFixed(items) {
  return items.reduce((sum, item) => sum + item.price * Number(item.qty), 0);
}
console.log(calcCartTotalFixed([{ price: 9.99, qty: '2' }])); // → 19.98 ✓

// ── STEP 2: Make the assumption executable (guard clause) ─────
function calcCartTotalSafe(items) {
  if (!Array.isArray(items)) {
    throw new TypeError('calcCartTotal: items must be an array, got ' + typeof items);
  }
  return items.reduce((sum, item) => {
    const qty = Number(item.qty);
    if (isNaN(qty)) {
      throw new TypeError(`calcCartTotal: item.qty is not numeric: ${JSON.stringify(item)}`);
    }
    return sum + item.price * qty;
  }, 0);
}

// ── STEP 3: Write a regression test ──────────────────────────
// (Jest / Vitest style)
function assertEqual(actual, expected, label) {
  const pass = Math.abs(actual - expected) < 0.001;
  console.log((pass ? '✓' : '✗') + ' ' + label);
  if (!pass) throw new Error(`Expected ${expected}, got ${actual}`);
}

assertEqual(calcCartTotalFixed([{ price: 10, qty: '3' }]),   30,    'string qty');
assertEqual(calcCartTotalFixed([{ price: 9.99, qty: 2 }]),   19.98, 'numeric qty');
assertEqual(calcCartTotalFixed([]),                           0,     'empty cart');
assertEqual(calcCartTotalFixed([{ price: 5, qty: '0' }]),    0,     'zero qty');

// ── Structured logger with levels and correlation ID ──────────
const LEVELS = { debug: 0, info: 1, warn: 2, error: 3 };
const LOG_LEVEL = process.env.LOG_LEVEL || 'info';

function log(level, message, context = {}) {
  if (LEVELS[level] < LEVELS[LOG_LEVEL]) return; // respect configured level
  const entry = {
    timestamp: new Date().toISOString(),
    level,
    message,
    ...context,
  };
  console[level === 'debug' ? 'log' : level](JSON.stringify(entry));
}

// ── Request middleware: attach correlation ID to every request ─
function withCorrelationId(handler) {
  return function(req, res) {
    const correlationId = req.headers['x-correlation-id'] || generateId();
    res.setHeader('x-correlation-id', correlationId);
    req.correlationId = correlationId;
    return handler(req, res);
  };
}

// ── Service function with full logging ─────────────────────────
async function processPayment(order, correlationId) {
  const ctx = { correlationId, orderId: order.id, amount: order.total };
  log('debug', 'processPayment enter', ctx);

  if (!order.paymentMethod) {
    log('error', 'processPayment: missing payment method', ctx);
    throw new Error('Payment method required');
  }

  const startMs = Date.now();
  try {
    const result = await paymentGateway.charge(order);
    log('info', 'processPayment success', {
      ...ctx,
      durationMs: Date.now() - startMs,
      transactionId: result.transactionId,
    });
    return result;
  } catch (err) {
    log('error', 'processPayment gateway error', {
      ...ctx,
      durationMs: Date.now() - startMs,
      error: err.message,
    });
    throw err;
  }
}

// With LOG_LEVEL=debug: debug + info + error entries all appear
// With LOG_LEVEL=info:  only info + error entries appear
// Filter by correlationId in log tool to trace a specific request

function generateId() {
  return Math.random().toString(36).slice(2, 10);
}

// ── Guard clauses vs. no guard — comparison ───────────────────

// WITHOUT guards: cryptic error far from the source
function displayUserProfile(user) {
  const name = formatName(user);
  const avatar = buildAvatarUrl(user.id);
  return { name, avatar };
}
function formatName(user) {
  return user.name.trim().toUpperCase(); // 'Cannot read properties of null (reading name)'
}
// Stack trace points to formatName line 2, not to whoever called displayUserProfile with null

// WITH guards: immediate, descriptive failure at the point of entry
function displayUserProfileSafe(user) {
  if (user === null || user === undefined) {
    throw new TypeError('displayUserProfile: user is required, got ' + user);
  }
  if (typeof user.id !== 'number') {
    throw new TypeError('displayUserProfile: user.id must be a number, got ' + typeof user.id);
  }
  if (typeof user.name !== 'string') {
    throw new TypeError('displayUserProfile: user.name must be a string, got ' + typeof user.name);
  }
  const name = user.name.trim().toUpperCase();
  const avatar = buildAvatarUrl(user.id);
  return { name, avatar };
}

// ── console.assert: document assumptions inline ───────────────
function divide(numerator, denominator) {
  console.assert(typeof numerator === 'number', 'divide: numerator must be number, got %s', typeof numerator);
  console.assert(typeof denominator === 'number', 'divide: denominator must be number, got %s', typeof denominator);
  console.assert(denominator !== 0, 'divide: denominator must not be 0, numerator=%d', numerator);
  return numerator / denominator;
}

// ── Binary search in code: add a midpoint checkpoint ─────────
function pipeline(rawInput) {
  const parsed    = parseInput(rawInput);       // Step 1
  const validated = validateSchema(parsed);     // Step 2
  // ---- midpoint checkpoint: is the state correct here? ----
  console.assert(
    Array.isArray(validated.items) && validated.items.length > 0,
    'pipeline midpoint: validated.items should be non-empty array',
    validated
  );
  const enriched  = enrichWithMetadata(validated);  // Step 3
  const rendered  = renderOutput(enriched);          // Step 4
  return rendered;
}
